<template>
  <section class="df-panel-reference">
    <header class="df-panel-hero">
      <div class="df-panel-heading"><span class="df-panel-hero-icon"><icon-layers /></span><div><h1>数据工厂</h1><p>按场景查找数据工具，生成、转换与校验测试数据，通过记录和标签复用结果。</p></div></div>
      <div class="df-panel-meta"><span><icon-desktop />{{ projectName }}</span><span><icon-apps />{{ catalogReady ? catalog.tools.length : '—' }} 个工具</span><span><icon-tags />{{ tagCount ?? '—' }} 个标签</span><span><icon-storage />{{ statisticsReady ? statistics.total_records : '—' }} 条记录</span></div>
      <svg class="df-panel-hero-art" viewBox="0 0 400 150" aria-hidden="true"><path d="M0 135 270 8M80 150 365 15M0 55l270 95M190 0l210 100" stroke="currentColor" opacity=".15"/><g fill="currentColor"><path d="m160 92 72-29 72 29-72 30z" opacity=".15"/><path d="m160 92 72 30 72-30v16l-72 30-72-30z" opacity=".25"/><path d="m160 62 72-29 72 29-72 30z" opacity=".35"/><path d="m160 62 72 30 72-30v16l-72 30-72-30z" opacity=".5"/><path d="m160 32 72-29 72 29-72 30z" opacity=".65"/><path d="m160 32 72 30 72-30v16l-72 30-72-30z" opacity=".8"/></g></svg>
    </header>
    <a-alert v-if="!projectId" type="info">未选择项目时可浏览全部工具，执行、记录和标签管理暂不可用。</a-alert>
    <a-alert v-if="error" type="warning" class="df-panel-error">{{ error }} <a-button type="text" size="mini" @click="$emit('refresh')">重试</a-button></a-alert>
    <div class="df-panel-metrics"><article v-for="metric in metrics" :key="metric.label" class="df-panel-metric" :class="metric.tone"><span><component :is="metric.icon" /></span><div><small>{{ metric.label }}</small><strong>{{ format(metric.value) }}</strong></div></article></div>
    <section class="df-panel-toolbar">
      <div class="df-panel-search"><a-input ref="searchInput" v-model="keyword" allow-clear placeholder="搜索工具名称、功能描述或分类，如：JSON、加密" :input-attrs="{ 'aria-label': '搜索数据工具' }"><template #prefix><icon-search /></template></a-input><kbd aria-hidden="true">⌘ K</kbd></div>
      <div class="df-panel-scenarios" role="group" aria-label="工具场景"><button :class="{ active: scenario === 'all' }" @click="scenario = 'all'">全部场景</button><button v-for="item in catalog.scenarios" :key="item.scenario" :class="{ active: scenario === item.scenario }" @click="scenario = item.scenario">{{ item.name }}</button></div>
      <div class="df-panel-actions"><a-button :disabled="!projectId" @click="$emit('reference', 'api')"><template #icon><icon-code-block /></template>API 引用</a-button><a-button :disabled="!projectId" @click="$emit('reference', 'ui')"><template #icon><icon-desktop /></template>UI 引用</a-button><a-button :disabled="!projectId" @click="$emit('history')"><template #icon><icon-history /></template>使用记录</a-button><a-button :disabled="!projectId" @click="$emit('tags')"><template #icon><icon-tags /></template>标签管理</a-button><a-button :loading="loading" @click="$emit('refresh')"><template #icon><icon-refresh /></template>刷新</a-button></div>
    </section>
    <div class="df-panel-main">
      <section ref="explorer" class="df-panel-explorer df-panel-surface">
        <header class="df-panel-section-head"><div><h2><icon-layers />工具探索</h2><p>{{ keyword.trim() ? '搜索匹配工具，点击即可打开；星标收藏保存在当前浏览器。' : '精选高频数据工具，覆盖数据生成、格式转换、校验验证等常用场景，提升测试数据处理效率。' }}</p></div><span v-if="scenario !== 'all' || keyword.trim()" class="df-panel-count">{{ matchingTools.length }} 个工具</span></header>
        <a-spin :loading="loading && !catalogReady" class="df-panel-explorer-spin">
          <div v-if="!keyword.trim()" class="df-panel-category-grid"><button v-for="category in categories" :key="category.category" class="df-panel-category-card" @click="$emit('category', category.category)"><div class="df-panel-card-heading"><span><component :is="categoryIcon(category.category)" /></span><h3>{{ category.name }}</h3></div><p>{{ category.description }}</p><footer><span><icon-bar-chart /> {{ statisticsReady ? '使用 ' + categoryUsage(category.category).toLocaleString() + ' 次' : '用量暂不可用' }}</span><b>进入工具 <icon-arrow-right /></b></footer></button></div>
          <div v-else class="df-panel-tool-results"><article v-for="tool in matchingTools" :key="tool.name" class="df-panel-tool-result"><button class="df-panel-tool-open" @click="$emit('tool', tool)"><span><component :is="categoryIcon(tool.category)" /></span><div><strong>{{ tool.display_name }}</strong><p>{{ tool.description }}</p><small>{{ categoryName(tool.category) }} · {{ scenarioName(tool.scenario) }}</small></div></button><a-button type="text" :aria-label="(isFavorite(tool.name) ? '取消收藏 ' : '收藏 ') + tool.display_name" :aria-pressed="isFavorite(tool.name)" :class="{ 'df-panel-starred': isFavorite(tool.name) }" @click="toggleFavorite(tool.name)"><icon-star-fill v-if="isFavorite(tool.name)" /><icon-star v-else /></a-button></article></div>
          <div v-if="catalogReady && !matchingTools.length" class="df-panel-empty"><icon-search /><strong>没有匹配的工具</strong><p>尝试其他关键词或切换场景</p><a-button @click="keyword = ''; scenario = 'all'">重置筛选</a-button></div>
          <div v-else-if="!catalogReady && !catalog.tools.length && !loading" class="df-panel-empty"><icon-tool /><strong>工具目录暂不可用</strong><a-button @click="$emit('refresh')">重新加载</a-button></div>
        </a-spin>
      </section>
      <aside class="df-panel-activity df-panel-surface">
        <div class="df-panel-activity-tabs" role="group" aria-label="快捷工具记录"><button :class="{ active: activity === 'recent' }" @click="activity = 'recent'"><icon-history />最近使用</button><button :class="{ active: activity === 'favorites' }" @click="activity = 'favorites'"><icon-star />收藏工具</button><button :class="{ active: activity === 'popular' }" @click="activity = 'popular'"><icon-fire />热门工具</button></div>
        <template v-if="activity === 'recent'"><div v-if="statisticsReady && recentRecords.length" class="df-panel-recent-list"><button v-for="record in recentRecords" :key="record.id" @click="$emit('record', record)"><span><component :is="categoryIcon(record.tool_category)" /></span><div><strong>{{ record.tool_display_name }}</strong><p>{{ record.preview || '查看执行结果' }}</p><small>{{ date(record.created_at) }}</small></div><icon-arrow-right /></button></div><div v-else class="df-panel-activity-empty"><EmptyBox /><h3>{{ !projectId ? '选择项目后查看最近使用' : statisticsReady ? '暂无最近使用记录' : '最近使用暂不可用' }}</h3><p>使用工具后，这里将展示您最近使用的工具，方便快速再次访问。</p><a-button @click="explore">去探索工具 <icon-arrow-right /></a-button></div></template>
        <template v-else-if="activity === 'favorites'"><p class="df-panel-activity-note">收藏仅保存在当前浏览器，按用户与项目分别管理。</p><div v-if="favoriteTools.length" class="df-panel-favorites"><div v-for="tool in favoriteTools" :key="tool.name"><button @click="$emit('tool', tool)"><component :is="categoryIcon(tool.category)" /><strong>{{ tool.display_name }}</strong><icon-arrow-right /></button><a-button type="text" :aria-label="'取消收藏 ' + tool.display_name" @click="toggleFavorite(tool.name)"><icon-star-fill /></a-button></div></div><div v-else class="df-panel-activity-empty"><icon-star class="df-panel-empty-icon" /><h3>还没有收藏工具</h3><p>搜索工具后，点击星标收藏常用工具。</p><a-button @click="explore">搜索工具 <icon-arrow-right /></a-button></div></template>
        <template v-else><p class="df-panel-activity-note">按当前项目最近 {{ recentRecords.length }} 条记录的使用频次排序</p><div v-if="statisticsReady && popularTools.length" class="df-panel-popular"><button v-for="(item, index) in popularTools" :key="item.tool.name" @click="$emit('tool', item.tool)"><i>{{ index + 1 }}</i><span>{{ item.tool.display_name }}</span><small>{{ item.count }} 次</small><icon-arrow-right /></button></div><div v-else class="df-panel-activity-empty"><icon-fire class="df-panel-empty-icon" /><h3>{{ statisticsReady ? '暂无热门工具记录' : '热门工具暂不可用' }}</h3><p>根据项目真实使用记录展示，不使用示例排名。</p></div></template>
      </aside>
    </div>
    <div class="df-panel-references">
      <section class="df-panel-tag-center df-panel-surface"><header class="df-panel-section-head"><div><h2><icon-tags />标签引用中心</h2><p>直接复制标签引用到 API 自动化请求、断言和 UI 自动化步骤中。</p></div></header><div v-if="referenceTags.length" class="df-panel-tag-list"><div v-for="tag in referenceTags.slice(0, 3)" :key="tag.id"><span><a-tag :color="tag.color || 'green'">{{ tag.code }}</a-tag><strong>{{ tag.name }}</strong></span><a-space><a-button size="mini" :disabled="!projectId" @click="$emit('copy-tag', tag.code, 'api')">复制 API</a-button><a-button size="mini" :disabled="!projectId" @click="$emit('copy-tag', tag.code, 'ui')">复制 UI</a-button></a-space></div></div><div class="df-panel-reference-actions"><a-button type="primary" :disabled="!projectId" @click="$emit('reference', 'api')"><template #icon><icon-code-block /></template>浏览 API 引用</a-button><a-button :disabled="!projectId" @click="$emit('reference', 'ui')"><template #icon><icon-desktop /></template>浏览 UI 引用</a-button></div><svg v-if="!referenceTags.length" class="df-panel-tag-art" viewBox="0 0 160 100" aria-hidden="true"><path d="M10 90 115 15l45 45-55 40" fill="currentColor" opacity=".06"/><g transform="rotate(-18 78 55)"><rect x="43" y="18" width="65" height="68" rx="12" fill="currentColor" opacity=".15"/><path d="m65 43 17-10 15 15-17 20-15-15z" fill="none" stroke="currentColor" stroke-width="3"/><circle cx="81" cy="45" r="3" fill="currentColor"/></g></svg></section>
      <section class="df-panel-record-center df-panel-surface"><header class="df-panel-section-head"><div><h2><icon-storage />记录引用中心</h2><p>已保存记录可直接复制引用，也可以点击查看具体执行结果。</p></div><span class="df-panel-count">{{ statisticsReady ? statistics.saved_records : '—' }} 条可引用记录</span></header><div v-if="referenceRecords.length" class="df-panel-saved-list"><article v-for="record in referenceRecords.slice(0, 3)" :key="record.id"><button @click="$emit('record', record)"><strong>{{ record.tool_display_name }}</strong><span>{{ record.preview }}</span></button><a-space><a-button size="mini" @click="$emit('copy-record', record, 'api')">复制 API</a-button><a-button size="mini" @click="$emit('copy-record', record, 'ui')">复制 UI</a-button></a-space></article></div><div v-else class="df-panel-reference-empty"><icon-file />{{ !projectId ? '选择项目后查看已保存记录' : referencesReady ? '当前项目下暂无已保存记录可引用' : '引用记录暂不可用' }}</div></section>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { Message } from '@arco-design/web-vue';
import { useAuthStore } from '@/store/authStore';
import { IconLayers, IconDesktop, IconApps, IconTags, IconStorage, IconSearch, IconCodeBlock, IconHistory, IconRefresh, IconBarChart, IconArrowRight, IconStar, IconStarFill, IconFire, IconTool, IconFontColors, IconLock, IconUserGroup, IconFile, IconClockCircle } from '@arco-design/web-vue/es/icon';
import type { DataFactoryCatalog, DataFactoryCategoryKey, DataFactoryRecord, DataFactoryReferenceMode, DataFactoryStatistics, DataFactoryTool } from '../types';
import './data-factory-panel.css';
const props = defineProps<{ catalog: DataFactoryCatalog; statistics: DataFactoryStatistics; tagCount: number | null; projectId: number | null; projectName: string; loading: boolean; error: string; catalogReady: boolean; statisticsReady: boolean; referencesReady: boolean; referenceRecords: DataFactoryRecord[]; referenceTags: { id: number; code: string; name: string; color: string }[] }>();
defineEmits<{ refresh: []; category: [category: DataFactoryCategoryKey]; tool: [tool: DataFactoryTool]; record: [record: DataFactoryRecord]; reference: [mode: DataFactoryReferenceMode]; history: []; tags: []; 'copy-tag': [code: string, mode: DataFactoryReferenceMode]; 'copy-record': [record: DataFactoryRecord, mode: DataFactoryReferenceMode] }>();
const auth = useAuthStore(); const keyword = ref(''); const scenario = ref('all'); const activity = ref('recent'); const favorites = ref<string[]>([]); const searchInput = ref<{ focus: () => void }>(); const explorer = ref<HTMLElement>();
const storageKey = computed(() => 'feice:data-factory:favorites:' + (auth.user?.id || 'anonymous') + ':' + (props.projectId || 'no-project'));
watch(storageKey, () => { try { const value: unknown = JSON.parse(localStorage.getItem(storageKey.value) || '[]'); favorites.value = Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string').slice(0, 200) : []; } catch { favorites.value = []; } }, { immediate: true });
watch(() => props.projectId, () => { keyword.value = ''; scenario.value = 'all'; activity.value = 'recent'; });
function isFavorite(name: string) { return favorites.value.includes(name); }
function toggleFavorite(name: string) { const next = isFavorite(name) ? favorites.value.filter(item => item !== name) : [...favorites.value, name]; try { localStorage.setItem(storageKey.value, JSON.stringify(next)); favorites.value = next; } catch { Message.warning('浏览器无法保存收藏，请检查本地存储设置'); } }
const categoryIcons = { string: IconFontColors, encoding: IconCodeBlock, random: IconFire, encryption: IconLock, test_data: IconUserGroup, json: IconCodeBlock, crontab: IconClockCircle };
const categoryIcon = (key: DataFactoryCategoryKey) => categoryIcons[key] || IconTool;
const categoryName = (key: string) => props.catalog.categories.find(item => item.category === key)?.name || key;
const scenarioName = (key: string) => props.catalog.scenarios.find(item => item.scenario === key)?.name || key;
const matchingTools = computed(() => { const query = keyword.value.trim().toLowerCase(); return props.catalog.tools.filter(tool => (scenario.value === 'all' || tool.scenario === scenario.value) && (!query || [tool.name, tool.display_name, tool.description, categoryName(tool.category)].some(value => value.toLowerCase().includes(query)))); });
const categories = computed(() => props.catalog.categories.filter(category => matchingTools.value.some(tool => tool.category === category.category)));
const categoryUsage = (key: string) => props.statistics.category_stats.find(item => item.tool_category === key)?.total || 0;
const recentRecords = computed(() => props.statisticsReady ? props.statistics.recent_records : []);
const favoriteTools = computed(() => props.catalog.tools.filter(tool => isFavorite(tool.name)));
const popularTools = computed(() => { const counts = new Map<string, number>(); recentRecords.value.forEach(record => counts.set(record.tool_name, (counts.get(record.tool_name) || 0) + 1)); return [...counts].map(([name, count]) => ({ tool: props.catalog.tools.find(tool => tool.name === name), count })).filter((item): item is { tool: DataFactoryTool; count: number } => !!item.tool).sort((a, b) => b.count - a.count || a.tool.display_name.localeCompare(b.tool.display_name)); });
const format = (value: number | null) => value == null ? '—' : value.toLocaleString('zh-CN');
const date = (value: string) => Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }) : '—';
const metrics = computed(() => [{ label: '总使用记录', value: props.statisticsReady ? props.statistics.total_records : null, icon: IconFile, tone: 'teal' }, { label: '已保存记录', value: props.statisticsReady ? props.statistics.saved_records : null, icon: IconHistory, tone: 'blue' }, { label: '标签数量', value: props.tagCount, icon: IconTags, tone: 'purple' }, { label: '可用工具', value: props.catalogReady ? props.catalog.tools.length : null, icon: IconLayers, tone: 'teal' }]);
function explore() { explorer.value?.scrollIntoView({ behavior: 'smooth', block: 'start' }); searchInput.value?.focus(); }
function shortcut(event: KeyboardEvent) {
  const dialogOpen = [...document.querySelectorAll<HTMLElement>('.arco-modal, .arco-drawer')].some(element => element.getClientRects().length > 0 && getComputedStyle(element).visibility !== 'hidden');
  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k' && !dialogOpen) { event.preventDefault(); explore(); }
}
onMounted(() => window.addEventListener('keydown', shortcut)); onBeforeUnmount(() => window.removeEventListener('keydown', shortcut));
const EmptyBox = defineComponent(() => () => h('svg', { viewBox: '0 0 150 120', class: 'df-panel-empty-box', 'aria-hidden': 'true' }, [h('path', { d: 'm35 52 40-18 40 18-40 20z', fill: '#ccf1ea' }), h('path', { d: 'm35 52 40 20v39L35 91z', fill: '#9cdfd5' }), h('path', { d: 'm75 72 40-20v39l-40 20z', fill: '#b2e9e1' }), h('path', { d: 'm35 52-14 18 41 18 13-16zm40 20 14 16 40-18-14-18z', fill: '#dcf7f1' }), h('path', { d: 'm74 17 2-10m15 21 10-5m-43 2-7-6', stroke: '#38bea9', 'stroke-width': 3, 'stroke-linecap': 'round' })]));
</script>
